mapper.sql:
FROM "offices" "o" INNER JOIN "operating_companies" "b" ON "b"."del_flag" = 0 AND "b"."available_flag" = 1 AND "b"."operating_company_id" = "o"."operating_company_id" INNER JOIN "agencies" "a" ON "a"."business_corp_id" = "b"."business_corp_id" AND "a"."del_flag" = 0 AND "a"."available_flag" = 1 WHERE "o"."del_flag" = 0 AND "a"."business_corp_id" = #{businessCorpId}
AND "o"."operating_company_id" = #{operatingCompanyId}
AND "o"."name" LIKE #{likeName}
AND "o"."available_flag" = #{availableFlag}
